package com.bank.interest.util;

import java.text.SimpleDateFormat;
import java.util.Date;

// ThreadLocal confinement: each thread gets its OWN SimpleDateFormat.
// SimpleDateFormat is NOT thread-safe, but confinement makes it safe.
public final class DateFormatterHolder {
    private static final ThreadLocal<SimpleDateFormat> FMT =
            ThreadLocal.withInitial(() -> new SimpleDateFormat("yyyy-MM-dd"));

    private DateFormatterHolder() {}

    public static String format(Date date) {
        return FMT.get().format(date);   // each thread uses its private copy
    }

    public static void clear() {
        FMT.remove();                    // always clear on pooled threads
    }
}
