package com.bank.interest.service;

import java.math.BigDecimal;
import java.math.RoundingMode;

// Stack confinement: all intermediate values are LOCAL variables.
// No shared field, so no synchronization is ever needed.
public class InterestCalculator {

    public BigDecimal calculateMonthlyInterest(BigDecimal principal, BigDecimal annualRate) {
        BigDecimal monthlyRate = annualRate.divide(new BigDecimal("1200"), 10, RoundingMode.HALF_UP);
        BigDecimal interest = principal.multiply(monthlyRate);   // local only
        return interest.setScale(2, RoundingMode.HALF_UP);       // confined to this stack
    }
}
