package com.bank.interest.service;

import com.bank.interest.model.Account;
import com.bank.interest.util.DateFormatterHolder;
import java.math.BigDecimal;
import java.util.Date;
import java.util.logging.Logger;

public class InterestPostingService {
    private static final Logger log = Logger.getLogger(InterestPostingService.class.getName());
    private final InterestCalculator calculator = new InterestCalculator();

    public void postInterest(Account account, BigDecimal annualRate) {
        try {
            // stack-confined computation — no lock needed
            BigDecimal interest = calculator.calculateMonthlyInterest(account.getBalance(), annualRate);
            account.credit(interest);
            // ThreadLocal-confined formatter — safe without lock
            String when = DateFormatterHolder.format(new Date());
            log.info(() -> "Posted interest " + interest + " to " + account.getAccountId()
                    + " on " + when + " by " + Thread.currentThread().getName());
        } finally {
            DateFormatterHolder.clear();   // prevent leak on pooled threads
        }
    }
}
