package com.bank.interest;

import com.bank.interest.model.Account;
import com.bank.interest.service.InterestPostingService;
import java.math.BigDecimal;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class InterestPostingDemo {
    public static void main(String[] args) throws InterruptedException {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        InterestPostingService service = new InterestPostingService();

        ExecutorService pool = Executors.newFixedThreadPool(2);
        // Run in parallel — safe because data is confined, not shared.
        pool.submit(() -> service.postInterest(rajesh, new BigDecimal("6.0")));
        pool.submit(() -> service.postInterest(priya,  new BigDecimal("4.5")));
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Rajesh new balance: " + rajesh.getBalance());
        System.out.println("Priya new balance:  " + priya.getBalance());
    }
}
